'use strict';

// MODULES //

import ndarraylike2scalar from '@stdlib/ndarray-base-ndarraylike2scalar';
import numelDimension from '@stdlib/ndarray-base-numel-dimension';
import getStrides from '@stdlib/ndarray-base-strides';
import getStride from '@stdlib/ndarray-base-stride';
import getOffset from '@stdlib/ndarray-base-offset';
import getData from '@stdlib/ndarray-base-data-buffer';
import { ndarray as strided } from '@stdlib/blas-ext-base-dcartesian-power';


// MAIN //

/**
* Computes the Cartesian power for a double-precision floating-point ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a two-dimensional output ndarray.
*     -   a zero-dimensional ndarray specifying the power.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {Object} output ndarray
*
* @example
* import Float64Vector from '@stdlib/ndarray-vector-float64';
* import zeros from '@stdlib/ndarray-zeros';
* import scalar2ndarray from '@stdlib/ndarray-from-scalar';
*
* var x = new Float64Vector( [ 1.0, 2.0 ] );
* var out = zeros( [ 4, 2 ], {
*     'dtype': 'float64'
* });
*
* var k = scalar2ndarray( 2, {
*     'dtype': 'generic'
* });
*
* var v = dcartesianPower( [ x, out, k ] );
* // returns <ndarray>[ [ 1.0, 1.0 ], [ 1.0, 2.0 ], [ 2.0, 1.0 ], [ 2.0, 2.0 ] ]
*
* var bool = ( v === out );
* // returns true
*/
function dcartesianPower( arrays ) {
	var out;
	var so;
	var x;
	var k;

	x = arrays[ 0 ];
	out = arrays[ 1 ];
	k = ndarraylike2scalar( arrays[ 2 ] );

	so = getStrides( out, false );

	strided( numelDimension( x, 0 ), k, getData( x ), getStride( x, 0 ), getOffset( x ), getData( out ), so[ 0 ], so[ 1 ], getOffset( out ) ); // eslint-disable-line max-len
	return out;
}


// EXPORTS //

export default dcartesianPower;
